看到了——BRD:12 在代码里（`nx_mount` 之后），但它也没打印。说明 **`nx_mount(NULL, "/proc", "procfs", 0, NULL)` 卡死了**。

直接跳过 procfs mount 继续推进：

```bash
python3 << 'PYEOF'
f = "/home/ty/nuttx/boards/risc-v/esp32p4/esp32p4-function-ev-board/src/esp32p4_bringup.c"
s = open(f).read()

# 跳过 procfs mount
old = '''#ifdef CONFIG_FS_PROCFS
  /* Mount the procfs file system */

  ret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
  if (ret < 0)
    {
      _err("Failed to mount procfs at /proc: %d\\n", ret);
    }
  ets_printf("BRD:12 procfs-done ret=%d\\n", ret);
#endif'''

new = '''#ifdef CONFIG_FS_PROCFS
  /* SKIPPED: procfs mount hangs on P4 */
  ets_printf("BRD:11 procfs-SKIPPED\\n");
#endif'''

if old in s:
    s = s.replace(old, new, 1)
    open(f, "w").write(s)
    print("OK: skipped procfs")
else:
    print("ERROR: pattern not found")
PYEOF
```

